        "description": "After breakfast, enjoy panoramic views of Pahalgam town and Lidder Valley. Start with Aru Valley which is a small village, 15 km upstream the Lidder River, The route is picturesque with ample campsites. This village is the starting point for treks to the Kolahoi glacier. Later, visit Chandanwari , 16 Km which is the starting point of sacred Amarnath Yatra. Chandanwari is famous for snow sledging on a snow bridge, enroute you can visit Hajan, an idyllic picnic spot and Betaab valley. Overnight at Pahalgam."
